style:
.tutorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 20px;
    padding: 15px;
}

.tutorial-card {
    background: #f8f9fa;
    padding: 15px;
    border-radius: 8px;
}

.tutorial-card.disabled {
    opacity: 0.4;
    pointer-events: none;
}

.tutorial-card h4 {
    margin-top: 0;
    padding-bottom: 8px;
}

.tutorial-links {
    margin-top: 12px;
}

.tutorial-links a {
    display: block;
    padding: 8px 0;
    text-decoration: none;
    color: #333;
}

.tutorial-links a:hover {
    color: #2490ef;
}

/* Disabled link styling */
a.disabled-link {
    color: #bfbfbf !important;
    cursor: not-allowed;
    pointer-events: none;
    text-decoration: none;
}

a.disabled-link:hover {
    color: #bfbfbf !important;
}

/* Topic-specific colors */
.getting-started h4 {
    color: #2490ef;
    border-bottom: 2px solid #2490ef;
}

.customer-management h4 {
    color: #28a745;
    border-bottom: 2px solid #28a745;
}

.selling-products h4 {
    color: #ff6b6b;
    border-bottom: 2px solid #ff6b6b;
}

.maintenance-service h4 {
    color: #9b59b6;
    border-bottom: 2px solid #9b59b6;
}

.vac-management h4 {
    color: #e67e22;
    border-bottom: 2px solid #e67e22;
}

.reports-analytics h4 {
    color: #16a085;
    border-bottom: 2px solid #16a085;
}
